-- Disposable PostgreSQL only. Every fixture is rolled back.
begin;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$
begin if condition is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(statement text,code text,label text) returns void language plpgsql as $$
declare failed boolean:=false;begin begin execute statement;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected % got %',label,code,sqlstate;end if;failed:=true;end;if not failed then raise exception 'FAIL: % unexpectedly succeeded',label;end if;raise notice 'PASS: %',label;end;$$;
insert into auth.users(id,email_confirmed_at) values
('00000000-0000-4000-a000-000000000001',now()),('00000000-0000-4000-a000-000000000002',now()),('00000000-0000-4000-a000-000000000003',now());
update public.profiles set username=case id when '00000000-0000-4000-a000-000000000001' then 'alice' when '00000000-0000-4000-a000-000000000002' then 'bob' else 'charlie' end,display_name='Test maker';
insert into public.projects(id,maker_id,name,tagline,description,category_id,status,published_at,publish_request_key,release_url) values('10000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000001','Vote fixture','A shipped vote test fixture',repeat('Description. ',20),(select id from public.categories where slug='developer-tools'),'published',now(),gen_random_uuid(),'https://example.test/votes');
set local role anon;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',true)$q$,'42501','anonymous vote mutation denied');
select pg_temp.expect_error($q$select public.get_my_project_votes('{}')$q$,'42501','anonymous viewer vote state denied');
select pg_temp.expect_error($q$select * from public.upvotes$q$,'42501','raw voter identities stay private');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',true)$q$,'22023','self upvote denied');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(public.set_project_upvote('10000000-0000-4000-a000-000000000001',true)='{"count":1,"upvoted":true}'::jsonb,'add returns authoritative count and viewer state');
select pg_temp.assert_true(public.set_project_upvote('10000000-0000-4000-a000-000000000001',true)->>'count'='1','repeated add is idempotent');
select pg_temp.assert_true(public.get_public_maker_totals('00000000-0000-4000-a000-000000000001')='{"projects":1,"upvotes":1}'::jsonb,'maker total derives from visible projects and valid votes');
select pg_temp.assert_true((select count(*)=1 from public.get_my_project_votes(array['10000000-0000-4000-a000-000000000001'::uuid])),'only own state is returned');
select pg_temp.expect_error($q$insert into public.upvotes values('00000000-0000-4000-a000-000000000003','10000000-0000-4000-a000-000000000001',now())$q$,'42501','direct actor spoofing denied');
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',null)$q$,'22023','null desired state denied');
select pg_temp.assert_true(public.set_project_upvote('10000000-0000-4000-a000-000000000001',false)='{"count":0,"upvoted":false}'::jsonb,'remove returns authoritative zero');
select pg_temp.assert_true(public.set_project_upvote('10000000-0000-4000-a000-000000000001',false)->>'count'='0','repeated removal is idempotent');
reset role;
select pg_temp.assert_true((select count(*)=1 and bool_and(withdrawn_at is not null and read_at is not null) from public.notifications),'remove withdraws notification and prevents unread spam');
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select public.set_project_upvote('10000000-0000-4000-a000-000000000001',true);
reset role;
select pg_temp.assert_true((select count(*)=1 and bool_and(withdrawn_at is null and read_at is not null) from public.notifications),'readd reuses read notification');
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000002';
select pg_temp.assert_true((select upvote_count=0 from public.get_public_project('10000000-0000-4000-a000-000000000001')),'suspended voters are excluded from counts');
select pg_temp.assert_true(public.get_public_maker_totals('00000000-0000-4000-a000-000000000001')->>'upvotes'='0','maker total excludes suspended voters');
set local role authenticated;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',false)$q$,'42501','suspended users cannot mutate');
reset role;
update private.account_controls set status='active' where user_id='00000000-0000-4000-a000-000000000002';
update private.account_settings set notify_upvotes=false where user_id='00000000-0000-4000-a000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000003',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.get_my_project_votes(array['10000000-0000-4000-a000-000000000001'::uuid])),'another viewer sees no other voter state');
select public.set_project_upvote('10000000-0000-4000-a000-000000000001',true);
reset role;
select pg_temp.assert_true((select count(*)=1 from public.notifications),'disabled preference prevents new upvote notifications');
update public.projects set status='hidden' where id='10000000-0000-4000-a000-000000000001';
select pg_temp.assert_true(public.get_public_maker_totals('00000000-0000-4000-a000-000000000001')='{"projects":0,"upvotes":0}'::jsonb,'hidden projects disappear from maker totals');
set local role authenticated;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',true)$q$,'22023','hidden project rejects votes');
reset role;
update public.projects set status='published' where id='10000000-0000-4000-a000-000000000001';
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',false)$q$,'22023','suspended maker project rejects votes');
reset role;
update private.account_controls set status='active' where user_id='00000000-0000-4000-a000-000000000001';
insert into private.rate_limits values('00000000-0000-4000-a000-000000000003','upvote',date_trunc('minute',now()),120,now()+interval '2 minutes') on conflict(subject_key,action,window_start) do update set count=120;
set local role authenticated;
select pg_temp.expect_error($q$select public.set_project_upvote('10000000-0000-4000-a000-000000000001',false)$q$,'P0001','mutation rate limit is enforced');
reset role;
select pg_temp.assert_true((select count(*)=2 from public.upvotes),'rate limit failure rolls back vote removal');
rollback;
